using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace Siderectomy {
 public sealed class DemoFlowCheck : MonoBehaviour {
  static bool started;string directory;readonly List<string> checks=new List<string>();
  public static void TryStart(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--flow-check");if(started||i<0||i+1>=args.Length)return;started=true;var go=new GameObject("FlowValidation");DontDestroyOnLoad(go);var test=go.AddComponent<DemoFlowCheck>();test.directory=args[i+1];Directory.CreateDirectory(test.directory);Application.logMessageReceived+=test.OnLog;test.StartCoroutine(test.Run());}
  void OnLog(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){File.AppendAllText(Path.Combine(directory,"运行错误.txt"),text+"\n"+stack+"\n");Application.Quit(1);}}
  void Require(bool ok,string name){if(!ok)throw new Exception("FLOW_CHECK: "+name);checks.Add("PASS "+name);}
  public static void Reveal(GameObject go){Canvas.ForceUpdateCanvases();foreach(var scroll in go.GetComponentsInParent<ScrollRect>()){if(scroll.content==null||!go.transform.IsChildOf(scroll.content))continue;var bounds=RectTransformUtility.CalculateRelativeRectTransformBounds(scroll.content,go.transform);if(scroll.vertical){float top=-bounds.max.y;float max=Mathf.Max(0,scroll.content.rect.height-scroll.viewport.rect.height);var pos=scroll.content.anchoredPosition;pos.y=Mathf.Clamp(top,0,max);scroll.content.anchoredPosition=pos;}if(scroll.horizontal){float max=Mathf.Max(0,scroll.content.rect.width-scroll.viewport.rect.width);var pos=scroll.content.anchoredPosition;pos.x=-Mathf.Clamp(bounds.min.x,0,max);scroll.content.anchoredPosition=pos;}scroll.StopMovement();Canvas.ForceUpdateCanvases();}}
  void Click(string name){var go=GameObject.Find(name);Require(go!=null,"存在按钮 "+name);Reveal(go);var button=go.GetComponent<Button>();Require(button!=null&&button.interactable,"按钮可用 "+name);var rect=(RectTransform)go.transform;var pointer=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);Require(hits.Count>0&&(hits[0].gameObject==go||hits[0].gameObject.transform.IsChildOf(go.transform)),"按钮没有遮挡 "+name);ExecuteEvents.Execute(go,pointer,ExecuteEvents.pointerClickHandler);}
  IEnumerator Frame(){yield return null;yield return null;}
  IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var camera=Camera.main;var canvas=FindObjectOfType<Canvas>();var mode=canvas.renderMode;var oldCamera=canvas.worldCamera;var oldTarget=camera.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(1600,900,24);camera.targetTexture=target;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;var pixels=new Texture2D(1600,900,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1600,900),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(directory,name+".png"),pixels.EncodeToPNG());camera.targetTexture=oldTarget;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=oldCamera;Destroy(pixels);target.Release();Destroy(target);yield return null;}
  IEnumerator Run(){yield return Frame();Require(FindObjectOfType<DemoFrontMenu>()!=null,"默认进入开始界面");yield return Capture("01_开始界面");Click("GameSettings");yield return Frame();Require(GameObject.Find("Volume").GetComponent<Slider>()!=null,"设置具有可调音量");Canvas.ForceUpdateCanvases();Require(GameObject.Find("Volume").GetComponent<Slider>().fillRect.rect.width<=620,"音量滑杆填充不越界");yield return Capture("01B_设置");Click("BackHome");yield return Frame();Click("NewProfile");yield return Frame();GameObject.Find("ProfileName").GetComponent<InputField>().text="分区存档验收";Click("ConfirmNewProfile");yield return Frame();Require(FindObjectOfType<OfficeView>()!=null&&DemoSession.Profile.currentLevel==1,"新档案进入办公室");string id=DemoSession.Profile.id;Require(!GameObject.Find("OfficeLevel6").GetComponent<Button>().interactable,"新档第六关锁定");DemoSession.Profile.highestUnlockedLevel=DemoProgression.LevelCount;DemoSaveStore.Save(DemoSession.Profile);UnityEngine.SceneManagement.SceneManager.LoadScene("Office");yield return Frame();Click("OfficeLevel4");yield return Frame();var view=FindObjectOfType<DemoMissionView>();Require(view!=null&&view.Simulation.Level.number==4,"办公室选择第四关");Require(!view.SecondaryMenuOpen,"进入关卡默认收起二级菜单");
   view.SetTab("operation");yield return Frame();var compactScroll=GameObject.Find("ActionScroll").GetComponent<ScrollRect>();Require(compactScroll.content.rect.height<=compactScroll.viewport.rect.height,"投送全部控件无需上下滚动");yield return Capture("09_紧凑投送面板");view.CloseSecondaryMenu();
   var hud=GameObject.Find("InventoryHUD").GetComponent<RectTransform>();var originalHudPos=hud.anchoredPosition;var originalHudSize=hud.sizeDelta;
   var drag=GameObject.Find("DragHeader");var pr=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,drag.transform.position)};ExecuteEvents.Execute(drag,pr,ExecuteEvents.beginDragHandler);pr.position+=new Vector2(80,50);ExecuteEvents.Execute(drag,pr,ExecuteEvents.dragHandler);Require(hud.anchoredPosition!=originalHudPos,"标题拖动改变物资栏位置");
   var edge=GameObject.Find("ResizeCorner1_-1");pr.position=RectTransformUtility.WorldToScreenPoint(null,edge.transform.position);ExecuteEvents.Execute(edge,pr,ExecuteEvents.beginDragHandler);pr.position+=new Vector2(100,-40);ExecuteEvents.Execute(edge,pr,ExecuteEvents.dragHandler);Require(hud.rect.width>originalHudSize.x&&hud.rect.height>originalHudSize.y,"边角拖动改变物资栏宽高");yield return Capture("10_物资栏拖动缩放");hud.GetComponent<DemoResizableHud>().Apply(originalHudPos,originalHudSize);
   var sidebar=GameObject.Find("Sidebar").GetComponent<RectTransform>();var comms=GameObject.Find("Communications").GetComponent<RectTransform>();Require(-sidebar.anchoredPosition.y+sidebar.rect.height<=-comms.anchoredPosition.y,"详情与通讯面板不重叠");
   view.SetTab("batch");yield return Frame();Require(GameObject.Find("Action_batch_info")==null,"移除手动信息批次入口");view.CloseSecondaryMenu();
string originalState=JsonUtility.ToJson(view.Simulation.Capture());
   for(int i=0;i<DemoMissionView.FunctionKeys.Length;i++){Require(view.HandleFunctionShortcut(DemoMissionView.FunctionKeys[i])&&view.SecondaryMenuOpen&&view.ActiveFunction==DemoMissionView.FunctionTabs[i],"快捷键打开对应二级菜单 "+DemoMissionView.FunctionKeys[i]);Require(view.HandleFunctionShortcut(DemoMissionView.FunctionKeys[i])&&!view.SecondaryMenuOpen,"同键收起菜单 "+DemoMissionView.FunctionKeys[i]);}
   Require(originalState==JsonUtility.ToJson(view.Simulation.Capture()),"快捷键只改变界面，不改变模拟状态");Require(GameObject.Find("HUD_resource_energy")!=null&&GameObject.Find("HUD_resource_matter")!=null&&GameObject.Find("HUD_resource_info")!=null,"左下资源图标列表包含三种基础资源");
   var inputRoot=PrototypeUi.Rect("ShortcutInputTest",FindObjectOfType<Canvas>().transform,0,0,100,25);var input=inputRoot.gameObject.AddComponent<InputField>();input.textComponent=PrototypeUi.Label(inputRoot,"Text","",0,0,100,25);EventSystem.current.SetSelectedGameObject(inputRoot.gameObject);Require(!view.HandleFunctionShortcut(KeyCode.Q),"输入文字时屏蔽功能快捷键");EventSystem.current.SetSelectedGameObject(null);Destroy(inputRoot.gameObject);
   view.OpenPauseMenu();yield return Frame();Require(!view.HandleFunctionShortcut(KeyCode.Q),"暂停弹窗阻止后台快捷键");Click("ResumeSimulation");yield return Frame();
   view.SetTab("operation");yield return Frame();var menu=GameObject.Find("AttackSelect").GetComponent<Dropdown>();menu.Show();yield return Frame();Require(!view.HandleFunctionShortcut(KeyCode.E),"下拉菜单打开时不误触快捷键");menu.Hide();yield return new WaitForSecondsRealtime(.2f);view.CloseSecondaryMenu();yield return Frame();

   foreach(string tab in new[]{"facility","batch","carrier","research","attackModule","operation","apply"}){Click("Tab_"+tab);yield return Frame();Require(GameObject.Find("ActionScroll").GetComponent<ScrollRect>()!=null,"滚动选项窗口 "+tab);foreach(var card in FindObjectsOfType<DemoOptionCard>())Require(card.Icon!=null,"统一图标占位 "+card.name);}
   Click("Tab_carrier");yield return Frame();var actionScroll=GameObject.Find("ActionScroll").GetComponent<ScrollRect>();var initialScroll=actionScroll.content.anchoredPosition;var wheel=new PointerEventData(EventSystem.current){scrollDelta=new Vector2(0,-1)};ExecuteEvents.Execute(actionScroll.gameObject,wheel,ExecuteEvents.scrollHandler);yield return Frame();Require(actionScroll.content.anchoredPosition!=initialScroll,"鼠标滚轮能滚动下级选项");Click("Action_carrier_dust");view.Simulation.Paused=false;view.Simulation.Advance(8);view.Simulation.Paused=true;view.Refresh();yield return Frame();view.QuickOperation("probe");yield return Frame();Click("Launch");yield return Frame();Require(view.Simulation.Missions.Count==1,"真实付费探测进入在途队列");Click("Tab_carrier");yield return Frame();Click("Action_carrier_dust");yield return Frame();
   var feed=FindObjectOfType<DemoLogFeed>();feed.Clear();view.Simulation.Log("日志测试：第一条");yield return new WaitForSecondsRealtime(.35f);Require(feed.GetComponentInChildren<CanvasGroup>().alpha>.99f,"日志淡入后不透明");yield return new WaitForSecondsRealtime(2.5f);Require(feed.GetComponentInChildren<CanvasGroup>().alpha>.99f,"日志不透明保持3秒");yield return new WaitForSecondsRealtime(1.1f);Require(feed.Count==0,"日志淡出后回收");view.Simulation.Log("测试消息一");view.Simulation.Log("测试消息二");yield return new WaitForSecondsRealtime(.4f);Require(feed.Count==2,"日志自下而上保留多条");Require(GameObject.Find("Logs")==null,"右侧移除日志区");
   var portrait=GameObject.Find("Communicator").GetComponent<Image>();var original=portrait.color;Click("Communicator");yield return Frame();Require(portrait.color!=original&&GameObject.Find("Dialogue_AAA")!=null,"点击通讯员变色并展开选项");Click("Dialogue_AAA");Require(GameObject.Find("ConversationMessage").GetComponent<Text>().text.Contains("AAA 已收到"),"AAA演示回复");Click("Dialogue_BBB");Require(GameObject.Find("ConversationMessage").GetComponent<Text>().text.Contains("BBB 已收到"),"BBB演示回复");yield return Capture("02_分区与模拟对话");Click("Dialogue_暂停键");yield return Frame();Require(view.Simulation.Paused,"对话暂停键冻结模拟");yield return Capture("03_暂停菜单");var saved=view.CaptureProgress();Click("SaveSimulation");yield return Frame();Require(FindObjectOfType<OfficeView>()!=null&&DemoSession.Profile.hasCheckpoint,"保存后退回办公室");yield return Capture("04_办公室已有局内存档");
   Click("OfficeMainMenu");yield return Frame();Click("ContinueGame");yield return Frame();yield return Capture("05_存档选择");Click("Load_"+id);yield return Frame();view=FindObjectOfType<DemoMissionView>();Require(view!=null&&view.Simulation.Paused,"开始界面读档回到暂停现场");Require(Math.Abs(view.Simulation.Time-saved.Time)<1e-8&&view.Simulation.Res.SequenceEqual(saved.resources),"读档保留计时和资源");Require(view.Simulation.Jobs.Count==saved.Jobs.Length&&view.Simulation.Jobs[0].left==saved.Jobs[0].left&&view.Simulation.Missions.Count==saved.Missions.Length&&view.Simulation.Missions[0].left==saved.Missions[0].left,"读档恢复制造与在途队列剩余时间");yield return Capture("06_局内读档恢复");view.Simulation.Paused=false;view.Simulation.Advance(21);view.Simulation.Paused=true;view.Refresh();yield return Frame();Require(view.Simulation.GlobalProbe,"读档后在途探测正确结算并揭示星系");Click("Tab_facility");yield return Frame();Click("Communicator");yield return new WaitForSecondsRealtime(.4f);yield return Capture("07_星系分区与通讯");view.CloseSecondaryMenu();yield return Frame();yield return Capture("08_图标栏与资源列表");
   view.OpenPauseMenu();yield return Frame();Click("ResetSimulation");yield return Frame();Require(view.Simulation.Time==0&&view.Simulation.Jobs.Count==0&&view.Simulation.Missions.Count==0&&!DemoSession.Profile.hasCheckpoint,"重新模拟清空现场并重开当前关");view.OpenPauseMenu();yield return Frame();Click("AbandonSimulation");yield return Frame();Require(FindObjectOfType<OfficeView>()!=null&&!DemoSaveStore.Load(id).hasCheckpoint,"放弃退出不保留局内进度");Click("OfficeMainMenu");yield return Frame();Click("ContinueGame");yield return Frame();Click("Delete_"+id);yield return Frame();Click("CancelDelete");yield return Frame();Require(DemoSaveStore.List().Any(e=>e.id==id),"取消删除保留存档");Click("Delete_"+id);yield return Frame();Click("ConfirmDelete");yield return Frame();Require(!DemoSaveStore.List().Any(e=>e.id==id),"删档完成且不残留在列表");
   File.WriteAllText(Path.Combine(directory,"界面与存档验收.txt"),string.Join("\n",checks));Application.Quit(0);
  }
 }
}
